-- Demo catalog for Aruvi. Run AFTER supabase-schema.sql in the Supabase SQL editor.
-- Replace each example.com download link with your real file link (Drive, S3 presigned URL, etc.).
insert into products
  (id, slug, name, category, price, tag, featured, short_description, description, features, gallery,
   shipping_label, delivery_note, is_digital_product, digital_label, digital_price, digital_access_link,
   enable_physical_version, physical_label, physical_price)
values
  ('prod_cloud_starter', 'cloud-starter-handbook', 'Cloud Starter Handbook', 'E-books', 499, 'Bestseller', true, 'A 6-week beginner plan to go from zero to your first deployed AWS project.', 'Cloud Starter Handbook walks you through core AWS services, IAM basics, and a hands-on mini project, with a checklist for every week so you always know the next step.', ARRAY['6-week study plan with weekly checklists','Core AWS services explained with simple diagrams','Hands-on mini project: static site on S3 + CloudFront'], '[{"id": "cloud-starter-handbook-1", "title": "E-books Frame 1", "eyebrow": "Front View", "background": "linear-gradient(135deg, #2dd4bf 0%, #0d9488 55%, #0f172a 100%)"}, {"id": "cloud-starter-handbook-2", "title": "E-books Frame 2", "eyebrow": "Detail Shot", "background": "linear-gradient(135deg, #2dd4bf 0%, #0d9488 55%, #0f172a 100%)"}, {"id": "cloud-starter-handbook-3", "title": "E-books Frame 3", "eyebrow": "In Use", "background": "linear-gradient(135deg, #2dd4bf 0%, #0d9488 55%, #0f172a 100%)"}]'::jsonb, 'Instant digital delivery', 'Download link delivered to your email right after payment.', true, 'Digital download', 499, 'https://example.com/replace-with-your-download-link', true, 'Printed copy', 899),
  ('prod_k8s_cheatsheets', 'kubernetes-cheat-sheet-bundle', 'Kubernetes Cheat Sheet Bundle', 'Bundles', 299, 'Digital Drop', true, 'kubectl, pods, deployments, services and troubleshooting on printable one-pagers.', 'A set of clean one-page cheat sheets you can keep next to your keyboard: the kubectl commands you actually use, common errors, and a debugging flow for broken pods.', ARRAY['10 printable one-page cheat sheets','Troubleshooting flow for CrashLoopBackOff and Pending pods','Updated whenever Kubernetes changes'], '[{"id": "kubernetes-cheat-sheet-bundle-1", "title": "Bundles Frame 1", "eyebrow": "Front View", "background": "linear-gradient(135deg, #5eead4 0%, #0369a1 55%, #0f172a 100%)"}, {"id": "kubernetes-cheat-sheet-bundle-2", "title": "Bundles Frame 2", "eyebrow": "Detail Shot", "background": "linear-gradient(135deg, #5eead4 0%, #0369a1 55%, #0f172a 100%)"}, {"id": "kubernetes-cheat-sheet-bundle-3", "title": "Bundles Frame 3", "eyebrow": "In Use", "background": "linear-gradient(135deg, #5eead4 0%, #0369a1 55%, #0f172a 100%)"}]'::jsonb, 'Instant digital delivery', 'Email delivery happens automatically after checkout.', true, 'Digital download', 299, 'https://example.com/replace-with-your-download-link', false, '', null),
  ('prod_cicd_templates', 'ci-cd-pipeline-templates', 'CI/CD Pipeline Templates', 'Bundles', 399, 'Hands-on', true, 'Ready-to-use GitHub Actions workflows with keyless AWS deploys (OIDC).', 'Copy, adapt and learn: tested workflow files for testing, building Docker images, and deploying to AWS without storing long-lived keys.', ARRAY['GitHub Actions workflows for test, build and deploy','OIDC role setup guide (no stored AWS keys)','Explained line by line so you learn, not just copy'], '[{"id": "ci-cd-pipeline-templates-1", "title": "Bundles Frame 1", "eyebrow": "Front View", "background": "linear-gradient(135deg, #5eead4 0%, #0369a1 55%, #0f172a 100%)"}, {"id": "ci-cd-pipeline-templates-2", "title": "Bundles Frame 2", "eyebrow": "Detail Shot", "background": "linear-gradient(135deg, #5eead4 0%, #0369a1 55%, #0f172a 100%)"}, {"id": "ci-cd-pipeline-templates-3", "title": "Bundles Frame 3", "eyebrow": "In Use", "background": "linear-gradient(135deg, #5eead4 0%, #0369a1 55%, #0f172a 100%)"}]'::jsonb, 'Instant digital delivery', 'Email delivery happens automatically after checkout.', true, 'Digital download', 399, 'https://example.com/replace-with-your-download-link', false, '', null),
  ('prod_terraform_templates', 'terraform-starter-templates', 'Terraform Starter Templates', 'Bundles', 449, 'New', false, 'Modular Terraform for a VPC, EC2 and an S3-backed remote state.', 'Starter modules for the infrastructure most beginner projects need, with remote state, variables and outputs set up the way teams actually do it.', ARRAY['VPC, subnets, security groups and EC2 modules','Remote state with S3 backend example','Comments that explain why, not just what'], '[{"id": "terraform-starter-templates-1", "title": "Bundles Frame 1", "eyebrow": "Front View", "background": "linear-gradient(135deg, #5eead4 0%, #0369a1 55%, #0f172a 100%)"}, {"id": "terraform-starter-templates-2", "title": "Bundles Frame 2", "eyebrow": "Detail Shot", "background": "linear-gradient(135deg, #5eead4 0%, #0369a1 55%, #0f172a 100%)"}, {"id": "terraform-starter-templates-3", "title": "Bundles Frame 3", "eyebrow": "In Use", "background": "linear-gradient(135deg, #5eead4 0%, #0369a1 55%, #0f172a 100%)"}]'::jsonb, 'Instant digital delivery', 'Email delivery happens automatically after checkout.', true, 'Digital download', 449, 'https://example.com/replace-with-your-download-link', false, '', null),
  ('prod_devops_planner', 'devops-weekly-planner', 'DevOps Weekly Planner', 'Planners', 599, 'Print', false, 'A printed planner to track study goals, labs, and project milestones.', 'A simple weekly layout for learners: set a goal, log a lab, note what broke, and track the projects you ship.', ARRAY['Weekly goal and lab log pages','Project milestone tracker','Lay-flat binding'], '[{"id": "devops-weekly-planner-1", "title": "Planners Frame 1", "eyebrow": "Front View", "background": "linear-gradient(135deg, #2dd4bf 0%, #0f766e 55%, #0f172a 100%)"}, {"id": "devops-weekly-planner-2", "title": "Planners Frame 2", "eyebrow": "Detail Shot", "background": "linear-gradient(135deg, #2dd4bf 0%, #0f766e 55%, #0f172a 100%)"}, {"id": "devops-weekly-planner-3", "title": "Planners Frame 3", "eyebrow": "In Use", "background": "linear-gradient(135deg, #2dd4bf 0%, #0f766e 55%, #0f172a 100%)"}]'::jsonb, 'Ships in 3 days', 'Standard delivery window is 3-5 working days.', false, '', null, null, false, '', null),
  ('prod_kubectl_stickers', 'kubectl-sticker-pack', 'kubectl Sticker Pack', 'Stickers', 199, 'Desk Gear', false, 'Waterproof laptop stickers for Kubernetes and cloud fans.', 'A pack of durable vinyl stickers for your laptop, bottle or notebook.', ARRAY['12 waterproof vinyl stickers','Matte finish','Peel-and-stick, residue-free'], '[{"id": "kubectl-sticker-pack-1", "title": "Stickers Frame 1", "eyebrow": "Front View", "background": "linear-gradient(135deg, #67e8f9 0%, #0369a1 55%, #0f172a 100%)"}, {"id": "kubectl-sticker-pack-2", "title": "Stickers Frame 2", "eyebrow": "Detail Shot", "background": "linear-gradient(135deg, #67e8f9 0%, #0369a1 55%, #0f172a 100%)"}, {"id": "kubectl-sticker-pack-3", "title": "Stickers Frame 3", "eyebrow": "In Use", "background": "linear-gradient(135deg, #67e8f9 0%, #0369a1 55%, #0f172a 100%)"}]'::jsonb, 'Ships in 3 days', 'Standard delivery window is 3-5 working days.', false, '', null, null, false, '', null)
